package com.dongqh.luckyhub.integration.simulator.controller;
import com.dongqh.luckyhub.common.result.ApiResponse;import com.dongqh.luckyhub.integration.simulator.*;import com.dongqh.luckyhub.rbac.annotation.RequirePermission;import com.dongqh.luckyhub.rbac.constant.PermissionCodes;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/simulators") public class SimulatorAdminController {private final SimulatorFailureRuleService service;public SimulatorAdminController(SimulatorFailureRuleService service){this.service=service;}@PostMapping("/failure-rules")@RequirePermission(PermissionCodes.SIMULATOR_CONTROL)public ApiResponse<Void> configure(@Valid @RequestBody ConfigureSimulatorFailureRuleCommand command){service.configure(command.fulfillmentType(),command.failureMode(),command.count());return ApiResponse.success();}}
